/**
 * Central image register. Every photograph the site shows is listed here with where it came from, so that
 * captions and alt text can never present an illustrative image as a real APEX facility, event or person.
 * Outputs are generated by scripts/optimize-images.mjs; keep widths in sync with that script.
 */
export type Provenance =
  /** Supplied by ClearMeat; documents real ClearMeat work. */
  | 'authentic'
  /** AI-generated concept for explaining a technology. Always labelled "Illustrative" on the page. */
  | 'illustrative';

type ImageSet = {
  widths: number[];
  width: number;
  height: number;
  fallback: 'jpg' | 'png';
  dir: 'photos' | 'apex';
  provenance: Provenance;
  /** Original file, for the asset register. */
  source: string;
};

/**
 * APEX Visual Asset Repository, round 1 (AI-generated). PREVIEW STAND-IN: until the full-size pack files are
 * supplied these are the ~324 x 180 px tiles cut from the pack's contact sheet, so they look soft when shown
 * large. When the originals arrive, set widths to what scripts/optimize-images.mjs outputs for them.
 */
const concept = (name: string): ImageSet => ({
  widths: [324],
  width: 324,
  height: 180,
  fallback: 'jpg',
  dir: 'apex',
  provenance: 'illustrative',
  source: `APEX Visual Asset Repository round 1 · ${name}.jpg (contact-sheet tile)`,
});

